package day1practice;

public class Program_Operators {

	public static void main(String[] args) {
		
		// TODO Auto-generated method stub
		
		int num1 = 10;
		int num2 = 5;
		System.out.println(num1+num2);
		System.out.println(num1-num2);
		System.out.println(num1*num2);
		System.out.println(num1/num2); // quotenit
		System.out.println(num1%num2); // mod to get the remider

	}

}
